(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.022-t*0.18)*15;
  const w2 = Math.cos(x*0.025-t*0.3)*12 + Math.sin(y*0.012+t*0.22)*18;
  const w3 = Math.sin((x+y)*0.01+t*0.15)*10 + Math.cos((x-y)*0.015-t*0.2)*8;
  const sx = x+w1+w3, sy = y+w2+w3;
  const src = [
    [120+Math.sin(t*0.5)*110, 60+Math.cos(t*0.35)*40, 0.07, 2.2, 1.0],
    [360+Math.cos(t*0.45)*100, 80+Math.sin(t*0.55)*50, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.3+1.5)*130, 40+Math.cos(t*0.6)*70, 0.055, 2.5, 1.1],
    [80+Math.cos(t*0.7+2)*70, 160+Math.sin(t*0.4+1)*60, 0.11, 1.6, 0.85],
    [400+Math.sin(t*0.38+3)*80, 180+Math.cos(t*0.8+1)*50, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+4)*100, 200+Math.sin(t*0.5+2)*80, 0.08, 2.0, 0.95],
    [180+Math.sin(t*0.6+5)*60, 120+Math.cos(t*0.42)*90, 0.13, 1.4, 0.8],
    [300+Math.cos(t*0.28+0.5)*90, 140+Math.sin(t*0.65+3)*70, 0.075, 2.3, 1.0],
    [60+Math.sin(t*0.55+2.5)*50, 220+Math.cos(t*0.48)*40, 0.1, 1.7, 0.9],
    [420+Math.cos(t*0.4+3.5)*70, 40+Math.sin(t*0.75+1.5)*55, 0.085, 2.1, 1.1]
  ];
  let act=0, inh=0, cross=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp), w2=Math.cos(d*f*0.8+t*sp*0.5+0.7);
    const w3=Math.sin(d*f*1.3-t*sp*0.8+2.1);
    act+=w1*w; inh+=w2*w; cross+=w3*w;
  }
  act/=10; inh/=10; cross/=10;
  const bg=(Math.sin(sx*0.035+sy*0.028+t*0.7)*0.5+Math.sin(sx*0.028-sy*0.038+t*0.95)*0.5);
  const bg2=(Math.cos(sx*0.045-sy*0.015+t*1.3)*0.4+Math.sin((sx+sy)*0.1+t*2.2)*0.3+Math.cos((sx-sy)*0.08-t*1.8)*0.3);
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3), sp2=Math.sin(dist*0.035+ang*5-t*1.0);
  const sp3=Math.cos(dist*0.06-ang*2-t*1.8)*0.5;
  const spiral=(sp1+sp2+sp3)/2.5;
  const rd1=Math.tanh((act-inh*0.6+bg*0.25+spiral*0.4)*2.5);
  const rd2=Math.tanh((cross-act*0.5+inh*0.4+bg2*0.2)*2.0);
  const interference=Math.sin(rd1*4+rd2*3+t*0.5)*0.3+Math.cos(rd1*2-rd2*5+t*0.8)*0.2;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t*0.7)*0.4+Math.sin((sx-sy)*0.11-t*0.5)*0.3)*1.8)*0.25;
  const voronoi=()=>{let md=999;for(let i=0;i<src.length;i++){const dx=sx-src[i][0],dy=sy-src[i][1];const d=Math.sqrt(dx*dx+dy*dy);if(d<md)md=d;}return md;};
  const vf=Math.sin(voronoi()*0.15-t*1.5)*0.15;
  const blend=rd1*0.45+rd2*0.25+cell*0.15+interference*0.1+vf*0.05;
  const v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,35,85],[15,65,120],[18,110,135],[45,155,130],[120,175,90],[195,185,65],[215,140,60],[195,85,55],[150,45,60],[90,22,55],[45,12,42],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.75+Math.sin(rd1*Math.PI)*0.15+Math.cos(rd2*Math.PI)*0.1;
  const edge=Math.abs(rd1)>0.65||Math.abs(rd2)>0.6?1.2:Math.abs(rd1)>0.4?1.05:0.95;
  const glow=Math.max(0,1-dist/300)*0.12*Math.sin(t*0.8)*0.5+0.88;
  const m=lum*edge*glow;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*m)|0
  ];
}
